// Tiny fake of the Bedrock script API: flat world, blocks, containers, entities.
export const S = { calls: { getBlock: 0, getEntities: 0, topmost: 0, events: 0 }, tick: 0, intervals: [], timeouts: [], dims: {}, worldDP: new Map(), entities: new Map(), nextId: 1, time: 500, log: [] };

const TOOLISH = /_axe$|_pickaxe$|_hoe$|_sword$|_shovel$|bucket|compass|empty_map/;
export class ItemStack {
  constructor(typeId, amount = 1) {
    if (typeof typeId !== "string" || !typeId.includes(":")) throw new Error("bad item " + typeId);
    this.typeId = typeId; this.amount = amount;
    this.maxAmount = /_axe$|_pickaxe$|_hoe$|_sword$|_shovel$|bucket$/.test(typeId) || typeId === "minecraft:water_bucket" ? 1 : typeId === "minecraft:compass" ? 64 : 64;
    this._dur = /_axe$|_pickaxe$|_hoe$|_sword$/.test(typeId) ? { damage: 0, maxDurability: 250 } : undefined;
  }
  clone() { const c = new ItemStack(this.typeId, this.amount); c._dur = this._dur && { ...this._dur }; return c; }
  isStackableWith(o) { return o.typeId === this.typeId && this.maxAmount > 1; }
  getComponent(n) { return n === "minecraft:durability" ? this._dur : undefined; }
}
export class Container {
  constructor(size) { this.size = size; this.slots = new Array(size).fill(undefined); }
  getItem(i) { return this.slots[i]?.clone(); }
  setItem(i, it) { this.slots[i] = it ? it.clone() : undefined; }
  get emptySlotsCount() { return this.slots.filter((s) => !s).length; }
  addItem(stack) {
    let left = stack.amount;
    for (let pass = 0; pass < 2 && left > 0; pass++) for (let i = 0; i < this.size && left > 0; i++) {
      const c = this.slots[i];
      if (pass === 0 && c && c.isStackableWith(stack) && c.amount < c.maxAmount) { const n = Math.min(left, c.maxAmount - c.amount); c.amount += n; left -= n; }
      else if (pass === 1 && !c) { const p = stack.clone(); p.amount = Math.min(left, stack.maxAmount); this.slots[i] = p; left -= p.amount; }
    }
    if (left <= 0) return undefined;
    const r = stack.clone(); r.amount = left; return r;
  }
}
export const BlockPermutation = { resolve: (id, states) => ({ typeId: id, states }) };

class Block {
  constructor(dim, p) { this.dimension = dim; this.x = p.x; this.y = p.y; this.z = p.z; this.location = { x: p.x, y: p.y, z: p.z }; }
  get typeId() { return this.dimension._get(this.x, this.y, this.z); }
  get isAir() { return this.typeId === "minecraft:air"; }
  get isLiquid() { return /water|lava/.test(this.typeId) && !/bucket/.test(this.typeId); }
  get isWaterlogged() { return false; }
  get permutation() { const d = this.dimension._states.get(`${this.x},${this.y},${this.z}`) ?? {}; return { getState: (n) => d[n] ?? (n === "liquid_depth" ? 0 : n === "growth" ? 0 : undefined), typeId: this.typeId }; }
  setType(id) { if (typeof id !== "string" || !/^[a-z_]+:[a-z_0-9]+$/.test(id)) throw new Error("bad block " + id); if (id === "minecraft:sugar_cane") throw new Error("no such block (sim: old name)"); this.dimension._set(this.x, this.y, this.z, id); }
  setPermutation(p) { this.dimension._set(this.x, this.y, this.z, p.typeId); this.dimension._states.set(`${this.x},${this.y},${this.z}`, p.states ?? {}); }
  below() { return this.dimension.getBlock({ x: this.x, y: this.y - 1, z: this.z }); }
  above() { return this.dimension.getBlock({ x: this.x, y: this.y + 1, z: this.z }); }
  getComponent(n) {
    if (n !== "minecraft:inventory") return undefined;
    if (!/chest|furnace/.test(this.typeId)) return undefined;
    const k = `${this.x},${this.y},${this.z}`;
    if (!this.dimension._containers.has(k)) this.dimension._containers.set(k, new Container(/furnace/.test(this.typeId) ? 3 : 27));
    return { container: this.dimension._containers.get(k) };
  }
}
const DROPS = {
  "minecraft:grass_block": "minecraft:dirt", "minecraft:reeds": "minecraft:sugar_cane", "minecraft:short_grass": null,
  "minecraft:stone": "minecraft:cobblestone", "minecraft:deepslate": "minecraft:cobbled_deepslate",
  "minecraft:coal_ore": "minecraft:coal", "minecraft:deepslate_coal_ore": "minecraft:coal", "minecraft:iron_ore": "minecraft:raw_iron",
  "minecraft:deepslate_iron_ore": "minecraft:raw_iron", "minecraft:deepslate_diamond_ore": "minecraft:diamond", "minecraft:redstone_ore": "minecraft:redstone",
  "minecraft:pumpkin_stem": null, "minecraft:melon_block": "minecraft:melon_slice",
};

export class Dimension {
  constructor(id) { this.id = id; this.blocks = new Map(); this._states = new Map(); this._containers = new Map(); }
  _get(x, y, z) {
    const k = `${x},${y},${z}`;
    if (this.blocks.has(k)) return this.blocks.get(k);
    if (this.id !== "minecraft:overworld") return "minecraft:air";
    if (Math.abs(x) > 150 || Math.abs(z) > 150) throw new Error("unloaded");
    if (y >= 63) return y === 63 ? "minecraft:grass_block" : "minecraft:air";
    if (y >= 50) return "minecraft:dirt";
    if (y <= -60) return "minecraft:bedrock";
    // a sprinkling of ore, the same every run
    const h = ((x * 73856093) ^ (y * 19349663) ^ (z * 83492791)) >>> 0;
    if (h % 89 === 0) return y < 0 ? "minecraft:deepslate_coal_ore" : "minecraft:coal_ore";
    if (y < 40 && h % 71 === 1) return y < 0 ? "minecraft:deepslate_iron_ore" : "minecraft:iron_ore";
    if (y < -30 && h % 181 === 2) return "minecraft:deepslate_diamond_ore";
    if (y < 20 && h % 151 === 3) return "minecraft:redstone_ore";
    return y < 0 ? "minecraft:deepslate" : "minecraft:stone";
  }
  _set(x, y, z, id) { this.blocks.set(`${x},${y},${z}`, id); }
  getBlock(p) { S.calls.getBlock++; if (S.profile && S.calls.getBlock % 97 === 0) { const st = new Error().stack.split("\n").slice(2, 5).map((l) => l.trim().replace(/^at /, "").replace(/\(file:.*\/scripts\//, "(").replace(/\)$/, "")).join(" < "); S.profile.set(st, (S.profile.get(st) ?? 0) + 1); } const x = Math.floor(p.x), y = Math.floor(p.y), z = Math.floor(p.z); this._get(x, y, z); return new Block(this, { x, y, z }); }
  getTopmostBlock({ x, z }) { S.calls.topmost++; for (let y = 100; y > -60; y--) { const b = this.getBlock({ x, y, z }); if (!b.isAir) return b; } }
  getEntities(o = {}) { S.calls.getEntities++;
    let out = [...S.entities.values()].filter((e) => e.dimension === this && e._valid);
    if (o.type) out = out.filter((e) => e.typeId === o.type);
    if (o.families) out = out.filter((e) => o.families.every((f) => e._families.includes(f)));
    if (o.excludeTypes) out = out.filter((e) => !o.excludeTypes.includes(e.typeId));
    if (o.location && o.maxDistance !== undefined) out = out.filter((e) => Math.hypot(e.location.x - o.location.x, e.location.y - o.location.y, e.location.z - o.location.z) <= o.maxDistance);
    if (o.location) out.sort((a, b) => Math.hypot(a.location.x - o.location.x, a.location.z - o.location.z) - Math.hypot(b.location.x - o.location.x, b.location.z - o.location.z));
    if (o.closest) out = out.slice(0, o.closest);
    return out;
  }
  spawnItem(stack, loc) { const e = new Entity("minecraft:item", this, loc); e._item = stack.clone(); return e; }
  spawnEntity(type, loc, opts) { const e = new Entity(type, this, loc); if (opts?.spawnEvent) e.triggerEvent(opts.spawnEvent); return e; }
  runCommand(cmd) {
    const m = cmd.match(/^setblock (-?\d+) (-?\d+) (-?\d+) air destroy$/);
    if (m) {
      let [x, y, z] = m.slice(1).map(Number);
      const drop = (id) => { const d = id in DROPS ? DROPS[id] : id; if (d) this.spawnItem(new ItemStack(d, 1), { x: x + 0.5, y: y + 0.5, z: z + 0.5 }); };
      const id = this._get(x, y, z);
      drop(id); this._set(x, y, z, "minecraft:air");
      if (id === "minecraft:reeds") { while (this._get(x, y + 1, z) === "minecraft:reeds") { y++; drop("minecraft:reeds"); this._set(x, y, z, "minecraft:air"); } }
    }
  }
  playSound() {}
  spawnParticle() {}
}

export class Entity {
  constructor(typeId, dim, loc) {
    this.id = String(S.nextId++ * 1000 + 17); this.typeId = typeId; this.dimension = dim; this.location = { ...loc }; this.nameTag = "";
    this._props = new Map(); this._dp = new Map(); this._valid = true; this._rot = { x: 0, y: 0 };
    this._families = typeId === "minecraft:player" ? ["player"] : /zombie|skeleton|creeper/.test(typeId) ? ["zombie", "undead", "monster", "mob"] : ["mob"];
    this._inv = typeId === "iv:villager" ? new Container(27) : undefined;
    if (typeId === "iv:villager") { this._props.set("iv:profession", 0); this._props.set("iv:working", false); this._props.set("iv:biome", 0); this._props.set("iv:sleeping", false); }
    S.entities.set(this.id, this);
  }
  get isValid() { return this._valid; }
  getComponent(n) {
    if (n === "minecraft:inventory") return this._inv ? { container: this._inv } : undefined;
    if (n === "minecraft:item") return this._item ? { itemStack: this._item } : undefined;
    if (n === "minecraft:is_baby") return this._baby ? {} : undefined;
    return undefined;
  }
  getProperty(n) { return this._props.get(n); }
  setProperty(n, v) { this._props.set(n, v); }
  getDynamicProperty(n) { return this._dp.get(n); }
  setDynamicProperty(n, v) { if (v === undefined) this._dp.delete(n); else this._dp.set(n, v); }
  triggerEvent(e) { S.calls.events++; this._lastEvent = e; (this._events ??= []).push(e); if (e === "minecraft:entity_born") this._baby = true; }
  teleport(loc) { this.location = { ...loc }; }
  setRotation(r) { this._rot = r; }
  getRotation() { return this._rot; }
  getVelocity() { return { x: 0, y: 0, z: 0 }; }
  applyImpulse(v) { this._impulse = v; if (this.typeId !== "iv:villager") this.location = { x: this.location.x + v.x * 2, y: this.location.y, z: this.location.z + v.z * 2 }; }
  get isOnGround() { return true; }
  removeEffect() {}
  matches(o) { return !o.families || o.families.every((f) => this._families.includes(f)); }
  applyDamage(n) { this._hp = (this._hp ?? 20) - n; if (this._hp <= 0) this.remove(); return true; }
  runCommand() {}
  addEffect() {}
  sendMessage(m) { console.log(m); }
  remove() { this._valid = false; S.entities.delete(this.id); }
  addTag(t) { (this._tags ??= new Set()).add(t); return true; }
  removeTag(t) { this._tags?.delete(t); return true; }
  hasTag(t) { return !!this._tags?.has(t); }
  getComponentHealth() { return undefined; }
}

const events = () => new Proxy({}, { get: () => ({ subscribe: () => {} }) });
export const world = {
  afterEvents: events(),
  beforeEvents: events(),
  getDimension(id) { return (S.dims[id] ??= new Dimension(id)); },
  getDynamicProperty(k) { return S.worldDP.get(k); },
  setDynamicProperty(k, v) { if (v === undefined) S.worldDP.delete(k); else S.worldDP.set(k, v); },
  getAbsoluteTime() { return S.tick; },
  getTimeOfDay() { return S.time; },
  getPlayers() { return [...S.entities.values()].filter((e) => e.typeId === "minecraft:player" && e._valid); },
  getEntity(id) { return S.entities.get(id); },
};
export const system = {
  get currentTick() { return S.tick; },
  runInterval(fn, n = 1) { S.intervals.push({ fn, n }); return S.intervals.length; },
  runTimeout(fn, n = 1) { S.timeouts.push({ fn, at: S.tick + n }); },
  run(fn) { S.timeouts.push({ fn, at: S.tick + 1 }); },
  afterEvents: events(),
  beforeEvents: events(),
};
